/**
 * Copy pinned runtime libraries from node_modules (installed from package-lock.json) into
 * vendor/ and record their SHA-256 checksums. The app loads vendor/ files only. It has no CDN.
 */
import { readFileSync, writeFileSync, mkdirSync, copyFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const out = path.join(root, 'vendor');
mkdirSync(out, { recursive: true });

const libs = [
    { pkg: 'chart.js', file: 'dist/chart.umd.js', dest: 'chart.umd.min.js', license: 'LICENSE.md', destLicense: 'chart.js.LICENSE.md' },
];

let md = '# Vendored runtime libraries\n\nGenerated by `npm run vendor`. Do not edit by hand.\n\n| Library | Version | File | SHA-256 | License |\n|---|---|---|---|---|\n';
for (const l of libs) {
    const dir = path.join(root, 'node_modules', l.pkg);
    const version = JSON.parse(readFileSync(path.join(dir, 'package.json'), 'utf8')).version;
    // Strip the trailing sourceMappingURL comment: the .map file is not shipped, and the reference would make
    // DevTools request a missing file. The code is otherwise byte-identical to the npm package.
    const upstream = readFileSync(path.join(dir, l.file), 'utf8');
    const stripped = upstream.replace(/\n?\/\/# sourceMappingURL=[^\n]*\s*$/, '\n');
    writeFileSync(path.join(out, l.dest), stripped);
    copyFileSync(path.join(dir, l.license), path.join(out, l.destLicense));
    const sha = createHash('sha256').update(readFileSync(path.join(out, l.dest))).digest('hex');
    const note = stripped === upstream ? '' : ` (trailing \`//# sourceMappingURL\` comment removed; upstream file sha256 \`${createHash('sha256').update(upstream).digest('hex')}\`)`;
    md += `| ${l.pkg} | ${version} | vendor/${l.dest} | \`${sha}\`${note} | MIT (vendor/${l.destLicense}) |\n`;
    console.log(`vendored ${l.pkg}@${version} sha256=${sha}`);
}
writeFileSync(path.join(out, 'VENDOR.md'), md);
